import json
task = json.load(open('task.json'))
parts = task['parts']
TOL = 0.005
n = len(parts)

def footprint(p):
    x,y,z = p['target_position']; sx,sy,sz = p['size_m']
    return (x-sx/2, x+sx/2, y-sy/2, y+sy/2)

def overlap_area(f1,f2):
    ix = max(0.0, min(f1[1],f2[1]) - max(f1[0],f2[0]))
    iy = max(0.0, min(f1[3],f2[3]) - max(f1[2],f2[2]))
    return ix*iy

# dependency: i depends on j if top of j ~= bottom of i and overlap > tiny
deps = {i: set() for i in range(n)}
for i in range(n):
    Pi=parts[i]; zB = Pi['target_position'][2]-Pi['size_m'][2]/2
    fi=footprint(Pi); ai=(fi[1]-fi[0])*(fi[3]-fi[2])
    for j in range(n):
        if i==j: continue
        Pj=parts[j]; zTop=Pj['target_position'][2]+Pj['size_m'][2]/2
        if abs(zB-zTop) < TOL:
            ov=overlap_area(fi, footprint(Pj))
            if ov > 0.3*ai:  # this part contributes significantly to i's support
                deps[i].add(j)

print("deps (i must come after set):")
for i in range(n):
    print(f"{i:2d} zBot={parts[i]['target_position'][2]-parts[i]['size_m'][2]/2:.3f} <- {sorted(deps[i])}")

# topological sort
placed=set(); order=[]
while len(order)<n:
    prog=False
    for i in range(n):
        if i in placed: continue
        if deps[i] <= placed:
            order.append(i); placed.add(i); prog=True
    if not prog:
        print("STUCK, remaining:", [i for i in range(n) if i not in placed])
        break

print("\nBuild order:", order)
# also print each with its z to see layering
for i in order:
    print(i, parts[i]['target_position'], parts[i]['size_m'])

